 HWND window=CreateWindowExW(0,L"OpenPilot",L"Library acceptance",WS_OVERLAPPEDWINDOW|WS_CLIPCHILDREN,-32000,-32000,1300,760,NULL,NULL,inst,NULL);if(!window)return 3;
