 ShowWindow(window,SW_SHOWNOACTIVATE);UpdateWindow(window);pump(30);

 CHECK("registered library roots loaded",libraryview_count()==3);CHECK("library zone visible below folder tree",IsWindowVisible(libraryview_tree()));libraryview_select(0);pump(20);CHECK("library mode replaces file panes",g_library_active&&IsWindowVisible(libraryview_window())&&!IsWindowVisible(g.panes[0].hwnd)&&!IsWindowVisible(g.panes[1].hwnd));
 fn_ctx context;pane_ctx(&context,active_pane(),FN_FROM_CODE,1);CHECK("hidden file selection has no operation authority",context.where==FN_ANYWHERE&&!(context.state&FN_S_ITEMS)&&!(context.state&FN_S_FOLDER));ctx_free(&context);
 HWND read=wait_button(L"Read PDF");CHECK("real catalogue helper exposes a readable PDF",read!=NULL);if(read){SendMessageW(read,BM_CLICK,0,0);uint64_t ready=GetTickCount64()+5000;while(g.pv_shown!=1&&GetTickCount64()<ready)pump(20);pump(100);printf("reader shown=%d active=%d status=%ls\n",g.pv_shown,g_library_active,active_pane()->status);CHECK("PDF opens alongside library catalogue",g.pv_shown==1&&IsWindowVisible(pdfview_window())&&IsWindowVisible(libraryview_window()));RECT a,b;GetWindowRect(libraryview_window(),&a);GetWindowRect(pdfview_window(),&b);CHECK("reader is a separate third pane",b.left>=a.right);wchar_t expected[32768];swprintf(expected,32768,L"%ls\\calibre\\Author\\First (1)\\First book.pdf",argv[1]);uint64_t opened=GetTickCount64()+15000;while(!library_pdf_opened(expected)&&GetTickCount64()<opened)pump(20);CHECK("reader helper opens the actual selected attachment",library_pdf_opened(expected));CHECK("preview target belongs to the selected library attachment",g.pv_want&&fpe_path_equal(g.pv_want,expected)&&!g.pv_src);HWND pin=wait_button(L"Pin reader");CHECK("reader state reaches the library controls",pin&&IsWindowVisible(pin));libraryview_select(0);pump(150);CHECK("reselecting the current library keeps the PDF open",g.pv_shown==1&&library_pdf_opened(expected)&&g.pv_want&&fpe_path_equal(g.pv_want,expected));preview_note(active_pane());CHECK("hidden folder changes cannot replace library reader",g.pv_shown==1);app_preview_close();CHECK("closing reader preserves library mode",g_library_active&&!g.pv_shown);pump(150);CHECK("reader close is reflected by the library controls",pin&&!IsWindowVisible(pin));library_action(5,expected);pump(50);CHECK("late follow requests cannot reopen a closed reader",!g.pv_shown);preview_show();pump(150);CHECK("native reader reopen restores library reader context",g.pv_shown==1&&pin&&IsWindowVisible(pin));app_preview_close();pump(100);libraryview_save_ratio(.72);CHECK("reader split is remembered per library",fabs(libraryview_reader_ratio()-.72)<.001);}
 libraryview_toggle(1);CHECK("checkbox membership creates a joint view",libraryview_checked_count()==2&&libraryview_checked(0)&&libraryview_checked(1)&&wait_rows(5));
 SendMessageW(libraryview_tree(),WM_KEYDOWN,VK_DOWN,0);CHECK("arrow focus leaves combined checkbox membership intact",libraryview_checked_count()==2&&libraryview_checked(0)&&libraryview_checked(1));
